{
  "identity": {
    "name": "Keeley Builders",
    "location": "Boise and the Treasure Valley area, Idaho (no street address published on the website)",
    "claims": [
      {
        "statement": "Keeley Builders was previously known as Keeley Enterprises and is based in the Boise, Idaho area.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/about-us",
        "quote": "Keeley Builders, previously known as Keeley Enterprises, is a small business based in the Boise, ID area"
      },
      {
        "statement": "Keeley Builders serves Boise, Eagle, Star, Meridian, Caldwell, Middleton, Nampa, and the surrounding Treasure Valley area in Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "Serving Boise, Eagle , Star, Meridian, Caldwell, Middleton, Nampa, and the entire Treasure Valley, ID area"
      },
      {
        "statement": "[redacted] is the owner of Keeley Builders and has over ten years of experience in home remodeling and handyman services.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "[redacted], owner of Keeley Builders, has over ten years of experience in home remodeling and handyman services."
      },
      {
        "statement": "The company does not publish a physical street address on the pages read.",
        "label": "inference",
        "sourceUrl": "https://www.keeleybuilders.com/contact-us",
        "quote": null
      }
    ]
  },
  "industry": {
    "industry": "Residential Remodeling, General Handyman Services, and Starter Home Construction",
    "activities": [
      "Kitchen and bathroom remodeling",
      "Room and second-floor additions",
      "Basement finishing and remodeling",
      "Flooring installation (LVP, laminate plank, engineered hardwood, tile)",
      "Interior and exterior painting",
      "General handyman repairs and home maintenance",
      "New build starter home construction"
    ],
    "claims": [
      {
        "statement": "Keeley Builders specializes in custom kitchen and bath remodeling, handyman services, and flooring installation.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "Keeley Builders is a small, local business specializing in custom kitchen and bath remodeling, handyman services, and flooring installation"
      },
      {
        "statement": "The company offers residential remodeling including kitchen and bathroom renovations, basement finishing, home additions, whole-home remodeling, floor installation, and interior or exterior painting.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/about-us",
        "quote": "We offer complete residential remodeling services , including kitchen and bathroom renovations, basement finishing , home additions , whole-home remodeling, floor installation , and interior or exterior painting ."
      },
      {
        "statement": "Keeley Builders also offers construction services for new build starter houses.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/about-us",
        "quote": "We have recently started offering new build starter houses , and love being part of the process of helping construct your new home!"
      },
      {
        "statement": "Although the handyman services page lists minor plumbing and electrical tasks such as leaky plumbing, light fixture installation, and electrical wiring among general home repairs, Keeley Builders is primarily a residential remodeler, handyman, and home builder rather than a dedicated HVAC, plumbing, or electrical trade contractor.",
        "label": "inference",
        "sourceUrl": "https://www.keeleybuilders.com/handyman-services",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.keeleybuilders.com/",
    "claims": [
      {
        "statement": "Keeley Builders states its operating hours are 8:00 AM to 5:00 PM, Monday through Friday.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/contact-us",
        "quote": "⏰ 8:00 AM – 5:00 PM, Monday-Friday"
      },
      {
        "statement": "The company provides free estimates and detailed project consultations before starting a project.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/about-us",
        "quote": "Yes! We provide detailed project consultations and estimates so you know exactly what to expect."
      },
      {
        "statement": "The website states that Keeley Builders works closely with Keeley Pest Control on new home construction projects.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/new-construction-services",
        "quote": "We also work closely with Keeley Pest Control to keep your home beautiful and bug free!"
      },
      {
        "statement": "The website footer indicates the site was designed by Surge Web Design.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "Designed by Surge Web Design."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The handyman services page states that [redacted] is a certified handyman.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/handyman-services",
        "quote": "[redacted] of Keeley Builders is not only a certified handyman but has years and years of experience in general home repair and maintenance."
      },
      {
        "statement": "No state contractor registration number or trade license number is displayed on the pages read.",
        "label": "inference",
        "sourceUrl": "https://www.keeleybuilders.com/about-us",
        "quote": null
      }
    ],
    "limitations": "Keeley Builders does not publish an Idaho contractor registration number or trade license numbers on its public website, and external state licensing registries cannot be checked using the available website fetcher."
  },
  "existingSoftware": [
    {
      "product": "embed.contractorforeman.com (lead_capture_form.php)",
      "purpose": "Embedded web lead capture form on the Contact Us page",
      "evidence": {
        "statement": "The Contact Us page embeds an iframe from embed.contractorforeman.com serving lead_capture_form.php.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/contact-us",
        "quote": "https://embed.contractorforeman.com/lead_capture_form.php?params=xMToLtPMChq9W8p1dh5dAGLTWv2sy0DMqLr0VbxJAGc0JriS83nDe9KyygzHG2tGT+7PI7hJPBTia18QtEB+bz66IxcAI+FgSTmjGsF5uYM="
      }
    },
    {
      "product": "googletagmanager.com (gtag/js)",
      "purpose": "Website tag management and analytics script",
      "evidence": {
        "statement": "The homepage loads a script from www.googletagmanager.com/gtag/js.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "https://www.googletagmanager.com/gtag/js?id=G-183KX7JDET"
      }
    },
    {
      "product": "analytics.ahrefs.com (analytics.js)",
      "purpose": "Website traffic analytics script",
      "evidence": {
        "statement": "The homepage loads an analytics script from analytics.ahrefs.com.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "https://analytics.ahrefs.com/analytics.js"
      }
    },
    {
      "product": "google.com/recaptcha (api.js)",
      "purpose": "Form spam protection script",
      "evidence": {
        "statement": "The homepage loads the reCAPTCHA script from www.google.com/recaptcha/api.js.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "https://www.google.com/recaptcha/api.js?render=explicit&onload=recaptchaLoadCallback"
      }
    },
    {
      "product": "js-agent.newrelic.com",
      "purpose": "Application performance and browser monitoring host referenced on the website",
      "evidence": {
        "statement": "The homepage references the host js-agent.newrelic.com.",
        "label": "fact",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "js-agent.newrelic.com"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The Contact Us page already uses an embedded lead capture form from embed.contractorforeman.com.",
      "label": "fact",
      "sourceUrl": "https://www.keeleybuilders.com/contact-us",
      "quote": "https://embed.contractorforeman.com/lead_capture_form.php?params=xMToLtPMChq9W8p1dh5dAGLTWv2sy0DMqLr0VbxJAGc0JriS83nDe9KyygzHG2tGT+7PI7hJPBTia18QtEB+bz66IxcAI+FgSTmjGsF5uYM="
    },
    {
      "statement": "The Testimonials page includes an on-site form for customers to submit reviews.",
      "label": "fact",
      "sourceUrl": "https://www.keeleybuilders.com/testimonials",
      "quote": "https://www.keeleybuilders.com/a/email_forms?id=49911 (post)"
    },
    {
      "statement": "No live chat widget, online scheduling widget, or paid advertising tracking pixels beyond general analytics are observable on the pages read.",
      "label": "inference",
      "sourceUrl": "https://www.keeleybuilders.com/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Phone calls or web form inquiries arriving outside stated weekday hours (8:00 AM – 5:00 PM, Monday-Friday) may experience delayed follow-up if not answered automatically.",
      "label": "hypothesis",
      "basis": "The Contact Us page lists weekday business hours of 8:00 AM to 5:00 PM Monday-Friday, and it is unknown from public pages whether automated lead replies or after-hours call answering are configured."
    }
  ],
  "existingSolutions": [
    {
      "solution": "embed.contractorforeman.com lead capture and construction project management system",
      "addresses": "Capturing web leads directly into the contractor's management software and managing estimates and projects.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Keeley Builders is outside ForgeX's target segment of 10-to-75-staff HVAC, plumbing, and electrical contractors and already uses an embedded Contractor Foreman lead capture form."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "Not applicable because no ForgeX automation solution is recommended."
  },
  "humanReview": [
    "No solution is recommended; human review requirements are not applicable."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Selling standardized field-service dispatch automations designed for 10-to-75-staff HVAC, plumbing, or electrical trade businesses to a small custom remodeling, handyman, and home building company risks poor workflow fit."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website publishes no service prices, average project values, or lead volumes, and no ForgeX solution is recommended."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Owner",
        "sourceUrl": "https://www.keeleybuilders.com/",
        "quote": "[redacted], owner of Keeley Builders, has over ten years of experience in home remodeling and handyman services."
      }
    ],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.keeleybuilders.com/contact-us"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How many full-time employees or crew members currently work at Keeley Builders?",
      "How are incoming inquiries from the embed.contractorforeman.com form and phone line currently followed up on?",
      "Does Keeley Builders run any paid lead-generation campaigns?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.keeleybuilders.com/",
        "usedFor": "Business identity, service area, core remodeling/handyman/construction activities, owner identification, and technical script inventory."
      },
      {
        "url": "https://www.keeleybuilders.com/about-us",
        "usedFor": "Company background (formerly Keeley Enterprises), full scope of remodeling and starter home construction services, and free estimate policy."
      },
      {
        "url": "https://www.keeleybuilders.com/contact-us",
        "usedFor": "Operating hours, phone contact channel, service area towns, and verification of the embedded embed.contractorforeman.com lead capture form."
      },
      {
        "url": "https://www.keeleybuilders.com/remodeling-services",
        "usedFor": "Verification of core remodeling activities (additions, kitchens, bathrooms, flooring, painting, basements)."
      },
      {
        "url": "https://www.keeleybuilders.com/handyman-services",
        "usedFor": "Verification of handyman service scope and owner's certified handyman statement."
      },
      {
        "url": "https://www.keeleybuilders.com/a/locations/hours",
        "usedFor": "Checking the dedicated hours page for additional location or operational details."
      },
      {
        "url": "https://www.keeleybuilders.com/new-construction-services",
        "usedFor": "Verification of custom starter home building process and relationship with Keeley Pest Control."
      },
      {
        "url": "https://www.keeleybuilders.com/testimonials",
        "usedFor": "Checking for on-site forms and operational details."
      },
      {
        "url": "https://www.keeleybuilders.com/gallery",
        "usedFor": "Verification of completed project types (remodeling, painting, decks, flooring, fences)."
      }
    ],
    "limitations": [
      "The website does not publish staff headcount or team size beyond describing the company as a 'small, local business' and 'small company'.",
      "The website does not publish a physical street address or state contractor license numbers.",
      "The website does not publish service pricing, average ticket size, or evidence of paid lead generation."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Keeley Builders is outside ForgeX's target segment of owner-led HVAC, plumbing, and electrical contractors with 10 to 75 staff who pay for leads. Its website shows it is a small residential remodeling, flooring, painting, starter home construction, and general handyman business, with no evidence of 10–75 staff or paid lead generation, and its Contact Us page already embeds a lead capture form from embed.contractorforeman.com."
  }
}
